create table if not exists public."ProductAttributeDefinition" (
  id text primary key default gen_random_uuid()::text,
  code text not null unique,
  "nameFa" text not null default '', "nameTr" text not null default '', "nameEn" text not null default '', "nameAr" text not null default '',
  "groupFa" text not null default '', "groupTr" text not null default '', "groupEn" text not null default '', "groupAr" text not null default '',
  "dataType" text not null default 'TEXT' check ("dataType" in ('TEXT','NUMBER','BOOLEAN','SELECT')),
  unit text not null default '', options jsonb not null default '[]'::jsonb,
  "isComparable" boolean not null default true, "isFilterable" boolean not null default false,
  "isPublished" boolean not null default true, "sortOrder" integer not null default 0,
  "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now()
);
create index if not exists "ProductAttributeDefinition_sort_idx" on public."ProductAttributeDefinition"("sortOrder",code);
create table if not exists public."ProductAttributeValue" (
  "productId" text not null references public."Product"(id) on delete cascade,
  "definitionId" text not null references public."ProductAttributeDefinition"(id) on delete cascade,
  "valueText" text, "valueNumber" numeric, "valueBoolean" boolean,
  "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now(),
  primary key ("productId","definitionId")
);
create index if not exists "ProductAttributeValue_definition_idx" on public."ProductAttributeValue"("definitionId","productId");
create table if not exists public."Collection" (
  id text primary key default gen_random_uuid()::text, slug text not null unique,
  "titleFa" text not null default '', "titleTr" text not null default '', "titleEn" text not null default '', "titleAr" text not null default '',
  "descriptionFa" text not null default '', "descriptionTr" text not null default '', "descriptionEn" text not null default '', "descriptionAr" text not null default '',
  "heroImageUrl" text not null default '',
  "seoTitleFa" text not null default '', "seoTitleTr" text not null default '', "seoTitleEn" text not null default '', "seoTitleAr" text not null default '',
  "seoDescriptionFa" text not null default '', "seoDescriptionTr" text not null default '', "seoDescriptionEn" text not null default '', "seoDescriptionAr" text not null default '',
  "isPublished" boolean not null default false, "sortOrder" integer not null default 0,
  "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now()
);
create index if not exists "Collection_publish_sort_idx" on public."Collection"("isPublished","sortOrder",slug);
create table if not exists public."CollectionProduct" (
  "collectionId" text not null references public."Collection"(id) on delete cascade,
  "productId" text not null references public."Product"(id) on delete cascade,
  "sortOrder" integer not null default 0,
  "createdAt" timestamptz not null default now(),
  primary key ("collectionId","productId")
);
create index if not exists "CollectionProduct_product_idx" on public."CollectionProduct"("productId","collectionId");
alter table public."ProductAttributeDefinition" enable row level security;
alter table public."ProductAttributeValue" enable row level security;
alter table public."Collection" enable row level security;
alter table public."CollectionProduct" enable row level security;
grant select on public."ProductAttributeDefinition",public."ProductAttributeValue",public."Collection",public."CollectionProduct" to anon,authenticated,service_role;
revoke insert,update,delete on public."ProductAttributeDefinition",public."ProductAttributeValue",public."Collection",public."CollectionProduct" from anon,authenticated;
drop policy if exists "public_read_attribute_definitions" on public."ProductAttributeDefinition";
create policy "public_read_attribute_definitions" on public."ProductAttributeDefinition" for select to anon,authenticated using ("isPublished"=true);
drop policy if exists "public_read_attribute_values" on public."ProductAttributeValue";
create policy "public_read_attribute_values" on public."ProductAttributeValue" for select to anon,authenticated using (exists(select 1 from public."Product" p where p.id="ProductAttributeValue"."productId" and p."isPublished"=true) and exists(select 1 from public."ProductAttributeDefinition" d where d.id="ProductAttributeValue"."definitionId" and d."isPublished"=true));
drop policy if exists "public_read_collections" on public."Collection";
create policy "public_read_collections" on public."Collection" for select to anon,authenticated using ("isPublished"=true);
drop policy if exists "public_read_collection_products" on public."CollectionProduct";
create policy "public_read_collection_products" on public."CollectionProduct" for select to anon,authenticated using (exists(select 1 from public."Collection" c where c.id="CollectionProduct"."collectionId" and c."isPublished"=true) and exists(select 1 from public."Product" p where p.id="CollectionProduct"."productId" and p."isPublished"=true));

create or replace function public.admin_attributes_bundle(p_token text,p_search text default '') returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_q text:=lower(trim(coalesce(p_search,''))); begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; return jsonb_build_object('definitions',(select coalesce(jsonb_agg(to_jsonb(x) order by x."sortOrder",x.code),'[]'::jsonb) from (select d.*,count(v."productId")::int as "usageCount" from public."ProductAttributeDefinition" d left join public."ProductAttributeValue" v on v."definitionId"=d.id where v_q='' or lower(concat_ws(' ',d.code,d."nameFa",d."nameTr",d."nameEn",d."nameAr",d."groupFa",d."groupEn")) like '%'||v_q||'%' group by d.id) x)); end $$;
create or replace function public.admin_upsert_attribute_definition(p_token text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_id text:=nullif(trim(coalesce(p_data->>'id','')),''); v_code text:=lower(trim(coalesce(p_data->>'code',''))); v_type text:=upper(trim(coalesce(p_data->>'dataType','TEXT'))); v_opts jsonb:=coalesce(p_data->'options','[]'::jsonb); begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if v_code !~ '^[a-z][a-z0-9_]{1,63}$' then raise exception 'invalid attribute code'; end if; if v_type not in ('TEXT','NUMBER','BOOLEAN','SELECT') then raise exception 'invalid data type'; end if; if trim(coalesce(p_data->>'nameFa',''))='' or trim(coalesce(p_data->>'nameEn',''))='' then raise exception 'Persian and English names required'; end if; if jsonb_typeof(v_opts)<>'array' then raise exception 'options must be array'; end if; if exists(select 1 from public."ProductAttributeDefinition" where code=v_code and (v_id is null or id<>v_id)) then raise exception 'attribute code already exists'; end if; if v_id is null then insert into public."ProductAttributeDefinition"(code,"nameFa","nameTr","nameEn","nameAr","groupFa","groupTr","groupEn","groupAr","dataType",unit,options,"isComparable","isFilterable","isPublished","sortOrder") values(v_code,trim(coalesce(p_data->>'nameFa','')),trim(coalesce(p_data->>'nameTr','')),trim(coalesce(p_data->>'nameEn','')),trim(coalesce(p_data->>'nameAr','')),trim(coalesce(p_data->>'groupFa','')),trim(coalesce(p_data->>'groupTr','')),trim(coalesce(p_data->>'groupEn','')),trim(coalesce(p_data->>'groupAr','')),v_type,trim(coalesce(p_data->>'unit','')),v_opts,coalesce((p_data->>'isComparable')::boolean,true),coalesce((p_data->>'isFilterable')::boolean,false),coalesce((p_data->>'isPublished')::boolean,true),coalesce(nullif(p_data->>'sortOrder','')::int,0)) returning id into v_id; else update public."ProductAttributeDefinition" set code=v_code,"nameFa"=trim(coalesce(p_data->>'nameFa','')),"nameTr"=trim(coalesce(p_data->>'nameTr','')),"nameEn"=trim(coalesce(p_data->>'nameEn','')),"nameAr"=trim(coalesce(p_data->>'nameAr','')),"groupFa"=trim(coalesce(p_data->>'groupFa','')),"groupTr"=trim(coalesce(p_data->>'groupTr','')),"groupEn"=trim(coalesce(p_data->>'groupEn','')),"groupAr"=trim(coalesce(p_data->>'groupAr','')),"dataType"=v_type,unit=trim(coalesce(p_data->>'unit','')),options=v_opts,"isComparable"=coalesce((p_data->>'isComparable')::boolean,true),"isFilterable"=coalesce((p_data->>'isFilterable')::boolean,false),"isPublished"=coalesce((p_data->>'isPublished')::boolean,true),"sortOrder"=coalesce(nullif(p_data->>'sortOrder','')::int,0),"updatedAt"=now() where id=v_id; if not found then raise exception 'attribute not found'; end if; end if; return jsonb_build_object('id',v_id,'code',v_code); end $$;
create or replace function public.admin_archive_attribute_definition(p_token text,p_id text) returns boolean language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; update public."ProductAttributeDefinition" set "isPublished"=false,"updatedAt"=now() where id=p_id; return found; end $$;
create or replace function public.admin_product_attributes(p_token text,p_product_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if not exists(select 1 from public."Product" where id=p_product_id) then raise exception 'product not found'; end if; return jsonb_build_object('definitions',(select coalesce(jsonb_agg(to_jsonb(d) order by d."sortOrder",d.code),'[]'::jsonb) from public."ProductAttributeDefinition" d where d."isPublished"=true),'values',(select coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) from public."ProductAttributeValue" v where v."productId"=p_product_id)); end $$;
create or replace function public.admin_set_product_attributes(p_token text,p_product_id text,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_item jsonb; v_def public."ProductAttributeDefinition"%rowtype; v_id text; v_raw text; v_count int:=0; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if not exists(select 1 from public."Product" where id=p_product_id) then raise exception 'product not found'; end if; if jsonb_typeof(coalesce(p_values,'[]'::jsonb))<>'array' then raise exception 'values must be array'; end if; delete from public."ProductAttributeValue" where "productId"=p_product_id; for v_item in select value from jsonb_array_elements(coalesce(p_values,'[]'::jsonb)) loop v_id:=nullif(trim(v_item->>'definitionId'),''); v_raw:=nullif(trim(coalesce(v_item->>'value','')),''); if v_id is null or v_raw is null then continue; end if; select * into v_def from public."ProductAttributeDefinition" where id=v_id and "isPublished"=true; if not found then continue; end if; if length(v_raw)>2000 then raise exception 'attribute value too long'; end if; if v_def."dataType"='NUMBER' then insert into public."ProductAttributeValue"("productId","definitionId","valueNumber") values(p_product_id,v_id,v_raw::numeric); elsif v_def."dataType"='BOOLEAN' then if lower(v_raw) not in ('true','false') then raise exception 'invalid boolean'; end if; insert into public."ProductAttributeValue"("productId","definitionId","valueBoolean") values(p_product_id,v_id,v_raw::boolean); elsif v_def."dataType"='SELECT' then if not exists(select 1 from jsonb_array_elements_text(v_def.options) x where x=v_raw) then raise exception 'invalid select option'; end if; insert into public."ProductAttributeValue"("productId","definitionId","valueText") values(p_product_id,v_id,v_raw); else insert into public."ProductAttributeValue"("productId","definitionId","valueText") values(p_product_id,v_id,v_raw); end if; v_count:=v_count+1; end loop; return jsonb_build_object('ok',true,'count',v_count); end $$;
create or replace function public.admin_collections_bundle(p_token text,p_search text default '') returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_q text:=lower(trim(coalesce(p_search,''))); begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; return jsonb_build_object('collections',(select coalesce(jsonb_agg(to_jsonb(x) order by x."sortOrder",x.slug),'[]'::jsonb) from (select c.*,count(cp."productId")::int as "productCount" from public."Collection" c left join public."CollectionProduct" cp on cp."collectionId"=c.id where v_q='' or lower(concat_ws(' ',c.slug,c."titleFa",c."titleTr",c."titleEn",c."titleAr")) like '%'||v_q||'%' group by c.id) x),'products',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'sku',p.sku,'nameFa',p."nameFa",'nameTr',p."nameTr",'nameEn',p."nameEn",'nameAr',p."nameAr") order by p."nameEn",p.sku),'[]'::jsonb) from public."Product" p where p."isPublished"=true)); end $$;
