 v_id; else update public."Collection" set slug=v_slug,"titleFa"=trim(coalesce(p_data->>'titleFa','')),"titleTr"=trim(coalesce(p_data->>'titleTr','')),"titleEn"=trim(coalesce(p_data->>'titleEn','')),"titleAr"=trim(coalesce(p_data->>'titleAr','')),"descriptionFa"=coalesce(p_data->>'descriptionFa',''),"descriptionTr"=coalesce(p_data->>'descriptionTr',''),"descriptionEn"=coalesce(p_data->>'descriptionEn',''),"descriptionAr"=coalesce(p_data->>'descriptionAr',''),"heroImageUrl"=trim(coalesce(p_data->>'heroImageUrl','')),"seoTitleFa"=coalesce(p_data->>'seoTitleFa',''),"seoTitleTr"=coalesce(p_data->>'seoTitleTr',''),"seoTitleEn"=coalesce(p_data->>'seoTitleEn',''),"seoTitleAr"=coalesce(p_data->>'seoTitleAr',''),"seoDescriptionFa"=coalesce(p_data->>'seoDescriptionFa',''),"seoDescriptionTr"=coalesce(p_data->>'seoDescriptionTr',''),"seoDescriptionEn"=coalesce(p_data->>'seoDescriptionEn',''),"seoDescriptionAr"=coalesce(p_data->>'seoDescriptionAr',''),"isPublished"=coalesce((p_data->>'isPublished')::boolean,false),"sortOrder"=coalesce(nullif(p_data->>'sortOrder','')::int,0),"updatedAt"=now() where id=v_id; if not found then raise exception 'collection not found'; end if; end if; return jsonb_build_object('id',v_id,'slug',v_slug); end $$;
